package cn.lili.common.security.session;
import cn.lili.modules.community.p0.support.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.util.*;
import static cn.lili.common.security.session.Stage1PersistenceTest.*;
import static cn.lili.modules.community.p0.support.Stage1Json.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@EnabledIfSystemProperty(named="s1.integration",matches="owned-run")
class Stage1PointCoverageTest {
    @BeforeAll static void start()throws Exception{initialize();}
    @AfterAll static void end()throws Exception{finish();}
    @BeforeEach void refresh(){new Stage1PersistenceTest().freshManagerSessions();}
    static Map<String,Object> pointPayload(String request,long version){return map("requestId",request,"expectedVersion",version,"type","COMMUNITY_PICKUP","name","S1_TEST合成点位","provinceCode","990000","cityCode","990100","districtCode","990101","address","S1_TEST新地址二号","contactName","合成联系人","phone","13800000000","opening",map("weekdays",List.of(1,2,3,4,5),"allDay",false,"start","09:00","end","17:00","crossDay",false),"reason","S1_TEST保存点位");}
    @Test void incompleteNativePointCannotEnableAndCurrentCorruptionRemovesOnlyThatMethod()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();String point=createPointFixture(owner,"COMMUNITY_PICKUP");var original=call(get(Stage1Routes.STORE+"/points/"+point),owner.login().session(),null,200);var history=original.getAsJsonArray("history").deepCopy();
        for(String field:List.of("phone","address","region","opening")){
            switch(field){case "phone"->db.update("UPDATE li_store_address SET mobile=NULL WHERE id=?",point);case "address"->db.update("UPDATE li_store_address SET address='' WHERE id=?",point);case "region"->db.update("UPDATE li_p0_point_control SET district_code='990100' WHERE point_id=?",point);case "opening"->db.update("UPDATE li_p0_point_control SET opening_hours=NULL WHERE point_id=?",point);}
            var bad=call(get(Stage1Routes.STORE+"/points/"+point),owner.login().session(),null,200).getAsJsonObject("point");assertFalse(bad.get("complete").getAsBoolean());assertTrue(bad.get("incompleteFields").toString().contains(field));call(post(Stage1Routes.STORE+"/points/"+point+"/enable"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST拒绝缺项启用"),422);assertEquals(0,db.count("SELECT enabled FROM li_p0_point_control WHERE point_id=?",point));assertEquals(0,db.count("SELECT version FROM li_p0_point_control WHERE point_id=?",point));
            db.update("UPDATE li_store_address SET mobile='13800000000',address='S1_TEST合成地址二号' WHERE id=?",point);db.update("UPDATE li_p0_point_control SET district_code='990101',opening_hours=? WHERE point_id=?",write(original.getAsJsonObject("point").get("opening")),point);
        }
        call(post(Stage1Routes.STORE+"/points/"+point+"/enable"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST完整启用"),200);var methods=object(deliveryMethods());methods.getAsJsonObject("COMMUNITY_PICKUP").addProperty("enabled",true);call(put(Stage1Routes.STORE+"/fulfillment"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"methods",methods,"reason","S1_TEST配送自提"),200);var goods=Stage1SupplyMatrixTest.createGoods(owner,2,List.of("MERCHANT_DELIVERY","COMMUNITY_PICKUP"),true);String goodsId=goods.getAsJsonObject("goods").get("id").getAsString();
        db.update("UPDATE li_store_address SET address='' WHERE id=?",point);var updated=call(get(Stage1Routes.STORE+"/goods/"+goodsId),owner.login().session(),null,200).getAsJsonObject("goods");assertEquals("[\"MERCHANT_DELIVERY\"]",updated.get("effectiveMethods").toString());assertTrue(updated.get("mockSaleable").getAsBoolean());assertTrue((Boolean)eligibility.evaluate(owner.store(),category,null).get("MOCK_READY"));var manager=call(get(Stage1Routes.MANAGER+"/stores/"+owner.store()+"/points"),operator,null,200);assertFalse(manager.getAsJsonArray("records").get(0).getAsJsonObject().get("complete").getAsBoolean());assertEquals(history.get(0),call(get(Stage1Routes.STORE+"/points/"+point),owner.login().session(),null,200).getAsJsonArray("history").get(1));
    }
    @Test void corruptSelectedPointIsRejectedEvenWhenAnotherValidPointKeepsTheMethodAvailable()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();String bad=createPointFixture(owner,"COMMUNITY_PICKUP"),good=createPointFixture(owner,"COMMUNITY_PICKUP");for(String point:List.of(bad,good))call(post(Stage1Routes.STORE+"/points/"+point+"/enable"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST多点"),200);
        var methods=object(deliveryMethods());methods.getAsJsonObject("COMMUNITY_PICKUP").addProperty("enabled",true);call(put(Stage1Routes.STORE+"/fulfillment"),owner.login().session(),map("requestId",req(),"expectedVersion",1,"methods",methods,"reason","S1_TEST可替代点"),200);var goods=Stage1SupplyMatrixTest.createGoods(owner,2,List.of("COMMUNITY_PICKUP"),true);String sku=goods.getAsJsonArray("skus").get(0).getAsJsonObject().get("id").getAsString();String code=req();codes.put(code,"S1_TEST_point_"+req());var buyer=residentLogin.login(code).session();var input=map("storeId",owner.store(),"items",List.of(map("skuId",sku,"quantity",1)),"method","COMMUNITY_PICKUP","pointId",bad);
        assertEquals("PASS",call(post(Stage1Routes.BUYER+"/precheck"),buyer,input,200).get("status").getAsString());db.update("UPDATE li_store_address SET mobile=NULL WHERE id=?",bad);var rejected=call(post(Stage1Routes.BUYER+"/precheck"),buyer,input,200);assertEquals("BLOCKED",rejected.get("status").getAsString());assertTrue(rejected.get("reasonCodes").toString().contains("POINT_UNAVAILABLE"));assertEquals(1,rejected.getAsJsonObject("candidatePoints").getAsJsonArray("COMMUNITY_PICKUP").size());input.put("pointId",good);assertEquals("PASS",call(post(Stage1Routes.BUYER+"/precheck"),buyer,input,200).get("status").getAsString());
    }
    @Test void hundredSaveReplaysAndAddressDisableRacePreserveStablePointAndHistory()throws Exception{
        var owner=ownerFixture();String id=createPointFixture(owner,"COMMUNITY_PICKUP");var command=pointPayload(req(),0);var first=call(put(Stage1Routes.STORE+"/points/"+id),owner.login().session(),command,200);for(int i=1;i<100;i++)assertEquals(first,call(put(Stage1Routes.STORE+"/points/"+id),owner.login().session(),command,200));assertEquals(2,db.count("SELECT COUNT(*) FROM li_p0_point_history WHERE point_id=?",id));assertEquals(1,db.count("SELECT version FROM li_p0_point_control WHERE point_id=?",id));var different=new LinkedHashMap<>(command);different.put("address","S1_TEST同键不同地址");call(put(Stage1Routes.STORE+"/points/"+id),owner.login().session(),different,409);
        var address=pointPayload(req(),1);address.put("address","S1_TEST并发地址三号");var disable=map("requestId",req(),"expectedVersion",1,"reason","S1_TEST并发停用");Stage1ConcurrencyTest.race(new Stage1ConcurrencyTest.Command("PUT",Stage1Routes.STORE+"/points/"+id,owner.login().session(),address),new Stage1ConcurrencyTest.Command("POST",Stage1Routes.STORE+"/points/"+id+"/disable",owner.login().session(),disable));assertEquals(2,db.count("SELECT version FROM li_p0_point_control WHERE point_id=?",id));assertEquals(3,db.count("SELECT COUNT(*) FROM li_p0_point_history WHERE point_id=?",id));assertEquals(1,db.count("SELECT COUNT(*) FROM li_store_address WHERE id=? AND store_id=? AND delete_flag=0",id,owner.store()));var rows=call(get(Stage1Routes.STORE+"/points/"+id),owner.login().session(),null,200).getAsJsonArray("history");assertEquals("S1_TEST合成地址二号",rows.get(2).getAsJsonObject().getAsJsonObject("snapshot").get("address").getAsString());
    }
}
